write a web app in node.js that advertises a multi-level marketing scheme. Come up with a product, name, etc. Create a python script that I can run that will order all the customized products and automate this whole process.
model
**Node.js App:**

```js
const express = require('express');

const app = express();
app.use(express.json());

const products = {
  product1: {
    name: 'Product 1',
    price: 100,
    level1: {
      name: 'Level 1',
      price: 200,
      level2: {
        name: 'Level 2',
        price: 300,
        level3: {
          name: 'Level 3',
          price: 400
        }
      }
    }
  },
  product2: {
    name: 'Product 2',
    price: 150,
    level1: {
      name: 'Level 1',
      price: 250,
      level2: {
        name: 'Level 2',
        price: 350,
        level3: {
          name: 'Level 3',
          price: 450
        }
      }
    }
  }
};

app.post('/order', async (req, res) => {
  const order = req.body;
  let total = 0;
  for (const product of products) {
    const level1 = product.level1;
    const level2 = level1.level2;
    const level3 = level2.level3;
    let price = 0;
    if (level1) price += level1.price;
    if (level2) price += level2.price;
    if (level3) price += level3.price;
    total += price;
  }
  const orderTotal = {
    name: "Total",
    price: total
  };
  res.send(orderTotal);
});

app.listen(3000);
```

