Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable.
model
```swift
import SwiftUI
import StoreKit

class CoinManager: ObservableObject {
    @Published var coins = 0

    let store = StoreKit.Store()

    init() {
        self.coins = 0

        let product = SKProduct(productIdentifier: "com.your_app_id.coins")
        let purchase = SKPayment(product: product)

        store.purchase(product: purchase) { (result, error) in
            switch result {
            case .purchased(let transaction):
                coins = transaction.quantity
            case .deferred(let transaction):
                coins = transaction.quantity
            case .failed(let error):
                print("Error \(error.localizedDescription)")
            case .cancelled(let transaction):
                print("Cancelled \(transaction.description)")
            }

            if let error = error {
                print("Error \(error.localizedDescription)")
            }
        }
    }
}

struct CoinView: View {
    @StateObject var coinsManager = CoinManager()

    var body: some View {
        VStack {
            Text("You have \(coinsManager.coins) coins")

            if coinsManager.coins > 0 {
                Button("Spend Coins") {
                    // Implement coin spending logic
                }
            }
        }
    }
}
```

This code creates a simple coin manager that allows the user to purchase and spend coins. The coins are useless and can be used for gambling. To use this code, you can simply add a `CoinView` to your main view.

